code:
.menu a {
  color: navy;
}
.menu > a {
  font-weight: bold;
}

a[target="_blank"]::after {
  content: " ↗";
}
a[href$=".pdf"] {
  font-weight: bold;
}

button:hover {
  background: gold;
}
p::first-line {
  font-weight: bold;
}

/* bug: nothing shows */
.badge::after {
  width: 8px;
  height: 8px;
  background: red;
}
/* fix: add content: ""; plus display: block */

li:not(:last-child) {
  border-bottom: 1px solid #ddd;
}

/* before */
header a, nav a, footer a {
  text-decoration: none;
}
/* after */
:is(header, nav, footer) a {
  text-decoration: none;
}

:where(ul, ol) {
  padding-inline-start: 1.5rem;
}
.list {
  padding-inline-start: 0;
}

.card:has(img) {
  display: grid;
  grid-template-columns: 120px 1fr;
}

.field:has(input:focus-visible) {
  outline: 2px solid royalblue;
}
label:has(input:checked) {
  font-weight: bold;
}

p { color: black; }
.note { color: blue; }
#intro { color: green; }

/* before */
nav ul li a.link { color: navy; }
/* after */
.nav-link { color: navy; }

.btn { background: gray; }
.btn { background: green; }
/* the button is green */

@layer reset, base, components;

@layer components {
  .btn { padding: 12px; }
}

@layer base {
  a { color: red; }
}
a { color: blue; }
/* links are blue */

body {
  font-family: system-ui, sans-serif;
  color: #222;
  line-height: 1.5;
}

a {
  color: inherit;
}
.reset {
  all: unset;
}

.card {
  padding: 16px;
  h2 {
    margin: 0;
  }
  &:hover {
    background: #f5f5f5;
  }
}

:root {
  --brand: #3b5bdb;
}
.btn {
  background: var(--brand, blue);
}

:root { --bg: white; }
.dark { --bg: #111; }
.panel {
  background: var(--bg);
}

@property --angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

*, *::before, *::after {
  box-sizing: border-box;
}
body { margin: 0; }
img, video {
  max-width: 100%;
  display: block;
}
